cat > ../clone-work/overwrite-review.ts <<'EOF'
import { initTRPC } from '@trpc/server';
import type { Overwrite } from '@trpc/server/core/internals/utils';

type OldOverwrite<TType, TWith> = TType extends any
  ? TWith extends any
    ? {
        [K in keyof TType | keyof TWith]: K extends keyof TWith
          ? TWith[K]
          : K extends keyof TType
          ? TType[K]
          : never;
      }
    : never
  : never;

declare const oldContext: OldOverwrite<{userId: string}, {extra: number} | undefined>;
oldContext.userId.toUpperCase();

declare const newContext: Overwrite<{userId: string}, {extra: number} | undefined>;
newContext.userId.toUpperCase();

const t = initTRPC.context<{ userId: string }>().create();
t.procedure
  .use(({ next }) => next({ ctx: Math.random() > 0.5 ? { extra: 1 } : undefined }))
  .query(({ ctx }) => ctx.userId);

t.procedure
  .use(({ next }) => next({ ctx: undefined }))
  .query(({ ctx }) => ctx.userId);

t.procedure
  .use(() => { throw new Error('blocked'); })
  .query(({ ctx }) => ctx.userId);
EOF
